static READY: AtomicBool = AtomicBool::new(false);
static mut SAMPLE: u16 = 0;

fn adc_isr() {
    unsafe { SAMPLE = read_adc(); }
    READY.store(true, Ordering::Release); // publish SAMPLE
}

